238		ghost := map[string]any{
239			"id": "ghost",
240			"rules": map[string]any{
241				"sandwich":     map[string]any{"enabled": false, "severity": 1},
242				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 100},
243			},
244		}
245		replaceStoredReportVersion(t, dir, "1", "0xblk", ghost)
246		cond, created, err := RegisterSuppression(dir, []byte(registerSuppressionSpec))
247		if err != nil || !created {
248			t.Fatalf("unregistered but complete declaration must not block registration: created=%v err=%v", created, err)
249		}
250		if cond.ID != "s1" || cond.Revoked {
251			t.Fatalf("registered condition wrong: %+v", cond)
252		}
253		// The saved declaration survived the commit with its own parameters,
254		// never values pulled from the enabled or a same-id registered version.
255		text := string(readArchiveFile(t, dir))
256		if !strings.Contains(text, `"ghost"`) || !strings.Contains(text, `"multiplier": 100`) {
257			t.Fatalf("saved declaration was rewritten:\n%s", text)
258		}
259		// The report still queries under its own saved parameters.
260		r, err := Query(dir, "1", "0xblk")
261		if err != nil {
262			t.Fatalf("report must still query under its saved declaration: %v", err)
263		}
264		if r.Version.ID != "ghost" || r.Version.Rules.Sandwich.Enabled {
265			t.Fatalf("saved off state not returned: %+v", r.Version)
266		}
267	}
268	
269	// TestRegisterSuppressionBuiltinIDDoesNotBypassValidation proves an id of
270	// "builtin" is validated like any other saved declaration: a complete one
271	// registers normally, a damaged one fails as corruption rather than being
272	// replaced by the in-code builtin.
273	func TestRegisterSuppressionBuiltinIDDoesNotBypassValidation(t *testing.T) {
274		dir := setupRegisterCorruptArchive(t)
275		builtinFull := map[string]any{
276			"id": "builtin",
277			"rules": map[string]any{
278				"sandwich":     map[string]any{"enabled": true, "severity": 3},
279				"displacement": map[string]any{"enabled": true, "severity": 2, "multiplier": 2},
280			},
281		}
282		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinFull)
283		if _, created, err := RegisterSuppression(dir, []byte(registerSuppressionSpec)); err != nil || !created {
284			t.Fatalf("a complete builtin-id declaration must not block registration: created=%v err=%v", created, err)
285		}
286	
287		dir = setupRegisterCorruptArchive(t)
288		builtinDamaged := map[string]any{
289			"id": "builtin",
290			"rules": map[string]any{
291				"sandwich":     map[string]any{"enabled": true, "severity": 3},
292				"displacement": map[string]any{"enabled": true, "severity": 2},
293			},
294		}
295		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinDamaged)
296		assertRegisterRefused(t, dir, registerSuppressionSpec, "s1", BuiltinVersionID, "multiplier")
297	}
298	
299	// TestRegisterSuppressionLegacyRecordWithoutVersionKey proves only a wholly
300	// absent version key keeps the built-in interpretation: the registration
301	// succeeds, the legacy record is written back without growing a version key
302	// and the new condition is appended.
303	func TestRegisterSuppressionLegacyRecordWithoutVersionKey(t *testing.T) {
304		dir := setupRegisterCorruptArchive(t)
305		dropVersionKey(t, dir, "0xblk")
306		cond, created, err := RegisterSuppression(dir, []byte(registerSuppressionSpec))
307		if err != nil || !created {
308			t.Fatalf("legacy record must not block registration: created=%v err=%v", created, err)
309		}
310		if cond.ID != "s1" {
311			t.Fatalf("unexpected condition: %+v", cond)
312		}
313		var doc struct {
314			Records []map[string]any `json:"records"`
315		}
316		if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
317			t.Fatal(err)
318		}
319		for _, rec := range doc.Records {
320			if rec["blockHash"] == "0xblk" {
321				if _, ok := rec["version"]; ok {
322					t.Fatalf("legacy record grew a version key: %v", rec)
323				}
324			}
325		}
326		// The legacy report still queries under the built-in rules.
327		r, err := Query(dir, "1", "0xblk")
328		if err != nil {
329			t.Fatalf("legacy report must still query: %v", err)
330		}
331		if r.Version != BuiltinVersion() {
332			t.Fatalf("legacy report version = %+v, want builtin", r.Version)
333		}
334	}
335	
336	// TestRegisterSuppressionOverCorruptArchiveMasksNoOutcome proves the
337	// integrity proof runs before any judgment about the submitted condition:
338	// an identical retry and a different-content conflict against an existing
339	// id, and an idempotent retry of an already revoked condition, all fail as
340	// corruption rather than returning created:false, a conflict or silently
341	// re-enabling the revoked condition.
342	func TestRegisterSuppressionOverCorruptArchiveMasksNoOutcome(t *testing.T) {
343		dir := setupRegisterCorruptArchive(t)
344		if _, created, err := RegisterSuppression(dir, []byte(registerSuppressionSpec)); err != nil || !created {
345			t.Fatalf("setup register: created=%v err=%v", created, err)
346		}
347		replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
348		before := readArchiveFile(t, dir)
349	
350		// Identical content would be a created:false no-op on an intact
351		// archive; over a corrupt report it is refused first.
352		if _, created, err := RegisterSuppression(dir, []byte(registerSuppressionSpec)); err == nil || created {
353			t.Fatalf("identical retry over a corrupt report: created=%v err=%v", created, err)
354		} else if !errors.Is(err, ErrCorruptVersion) {
355			t.Fatalf("identical retry error = %v, want ErrCorruptVersion", err)
356		}
357	
358		// Different content would be a conflict; corruption wins instead and is
359		// never misreported as ErrSuppressionConflict.
360		conflict := strings.Replace(registerSuppressionSpec, `"known bot war"`, `"other reason"`, 1)
361		_, _, cerr := RegisterSuppression(dir, []byte(conflict))
362		if !errors.Is(cerr, ErrCorruptVersion) || errors.Is(cerr, ErrSuppressionConflict) {
363			t.Fatalf("conflict over a corrupt report: %v, want ErrCorruptVersion (not a conflict)", cerr)
364		}
365		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
366			t.Fatal("refused registrations changed the archive")
367		}
368	
369		// A revoked condition keeps its flag: the failed retries never wrote.
370		var doc struct {
371			Suppressions []Suppression `json:"suppressions"`
372		}
373		if err := json.Unmarshal(before, &doc); err != nil {
374			t.Fatal(err)
375		}
376		for _, c := range doc.Suppressions {
377			if c.ID == "s1" && c.Revoked {
378				t.Fatalf("condition was revoked by a failed registration: %+v", c)
379			}
380		}
381	}
382	
383	// TestRegisterSuppressionRevokedConditionNotReenabledOverCorruption proves
384	// the fixed post-revocation behavior — an identical retry never re-enables
385	// a revoked condition — cannot be masked or triggered across a corrupt
386	// report: the retry fails as corruption and the revoked flag survives.
387	func TestRegisterSuppressionRevokedConditionNotReenabledOverCorruption(t *testing.T) {
388		dir := setupRegisterCorruptArchive(t)
389		registerRevocationSpec(t, dir)
390		if _, changed, err := RevokeSuppression(dir, "s1"); err != nil || !changed {
391			t.Fatalf("setup revoke: changed=%v err=%v", changed, err)
392		}
393		replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
394		before := readArchiveFile(t, dir)
395	
396		cond, created, err := RegisterSuppression(dir, []byte(revocationSpec))
397		if err == nil {
398			t.Fatalf("retry over a corrupt report succeeded: created=%v %+v", created, cond)
399		}
400		if !errors.Is(err, ErrCorruptVersion) {
401			t.Fatalf("error = %v, want ErrCorruptVersion", err)
402		}
403		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
404			t.Fatal("failed retry changed the archive")
405		}
406		conds, err := ListSuppressions(dir)
407		if err != nil {
408			t.Fatal(err)
409		}
410		for _, c := range conds {
411			if c.ID == "s1" && !c.Revoked {
412				t.Fatal("failed retry re-enabled the revoked condition")
413			}
414		}
415	}
416	
417	// TestRegisterSuppressionSuccessAppendsOnlyCondition proves a healthy
418	// archive still accepts new conditions and a successful registration touches
419	// nothing but the suppressions section: report conclusions and swap
420	// evidence, the versions registry and enabled marker, existing processing
421	// records and review history survive byte for byte, the new condition is
422	// appended last with revoked:false and a second condition still registers.
423	func TestRegisterSuppressionSuccessAppendsOnlyCondition(t *testing.T) {
424		dir := t.TempDir()
425		register(t, dir, candidateVersionSpec)
426		if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); err != nil {
427			t.Fatal(err)
428		}
429		if _, err := EnableVersion(dir, "candC"); err != nil {
430			t.Fatal(err)
431		}
432		spec0 := `{"id":"s0","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":0,"endHeight":50,"reason":"old"}`
433		if _, _, err := RegisterSuppression(dir, []byte(spec0)); err != nil {
434			t.Fatal(err)
435		}
436		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
437			t.Fatal(err)
438		}
439		if _, err := SubmitReview(dir, ReviewSubmission{
440			ChainID: "1", BlockHash: "0xa", TxHash: "0xvictim", Kind: "displacement",
441			SubmissionID: "rev-1", Operator: "alice", Reason: "looks fine",
442			Status: ReviewStatusFalsePositive, ExpectedVersion: 0,
443		}); err != nil {
444			t.Fatal(err)
445		}
446		// Revoke s0 so the archive also carries a revoked condition that must be
447		// preserved as-is.
448		if _, changed, err := RevokeSuppression(dir, "s0"); err != nil || !changed {
449			t.Fatalf("revoke s0: changed=%v err=%v", changed, err)
450		}
451		before := readEnableSkeleton(t, dir)
452	
453		cond, created, err := RegisterSuppression(dir, []byte(registerSuppressionSpec))
454		if err != nil || !created {
455			t.Fatalf("register s1: created=%v err=%v", created, err)
456		}
457		if cond.ID != "s1" || cond.Revoked || cond.StartHeight != 100 || cond.EndHeight != 200 {
458			t.Fatalf("registered condition wrong: %+v", cond)
459		}
460	
461		after := readEnableSkeleton(t, dir)
462		if !reflect.DeepEqual(before.Records, after.Records) {
463			t.Fatal("historical reports changed on registration")
464		}
465		if !reflect.DeepEqual(before.Versions, after.Versions) {
466			t.Fatal("version declarations changed on registration")
467		}
468		if after.EnabledVersion != before.EnabledVersion {
469			t.Fatalf("enabled marker changed on registration: %q -> %q", before.EnabledVersion, after.EnabledVersion)
470		}
471		if !reflect.DeepEqual(before.AlertRecords, after.AlertRecords) {
472			t.Fatal("alert processing records changed on registration")
473		}
474		if !reflect.DeepEqual(before.Reviews, after.Reviews) {
475			t.Fatal("manual reviews changed on registration")
476		}
477		if len(after.Suppressions) != len(before.Suppressions)+1 {
478			t.Fatalf("suppressions count = %d, want %d (append only)", len(after.Suppressions), len(before.Suppressions)+1)
479		}
480		if !reflect.DeepEqual(before.Suppressions, after.Suppressions[:len(before.Suppressions)]) {
481			t.Fatal("existing conditions changed on registration")
482		}
483		if after.Suppressions[len(after.Suppressions)-1] != cond {
484			t.Fatalf("appended condition = %+v, want %+v", after.Suppressions[len(after.Suppressions)-1], cond)
485		}
486	
487		// A second new condition still registers, and the appended order holds.
488		spec2 := `{"id":"s2","chainId":"2","pool":"p2","kind":"displacement","channel":"ops","startHeight":0,"endHeight":9,"reason":"r2"}`
489		if _, created, err := RegisterSuppression(dir, []byte(spec2)); err != nil || !created {
490			t.Fatalf("register s2: created=%v err=%v", created, err)
491		}
492		conds, err := ListSuppressions(dir)
493		if err != nil {
494			t.Fatal(err)
495		}
496		if len(conds) != 3 || conds[0].ID != "s0" || !conds[0].Revoked ||
497			conds[1].ID != "s1" || conds[1].Revoked || conds[2].ID != "s2" {
498			t.Fatalf("conditions after appends = %+v", conds)
499		}
500		// Report conclusions, evidence and review history are still intact.
501		r, err := Query(dir, "1", "0xa")
502		if err != nil {
503			t.Fatalf("report query after registration: %v", err)
504		}
505		if len(r.Findings) != 1 || r.Findings[0].TxHash != "0xvictim" ||
506			r.Findings[0].Kind != "displacement" || r.Findings[0].Severity != 4 ||
507			len(r.Findings[0].Evidence) != 2 {
508			t.Fatalf("report conclusions/evidence changed: %+v", r.Findings)
509		}
510	}
