1	package mevwatch
2	
3	// Regression coverage for `reviews submit` rewriting unrelated alerting
4	// evidence. A successful submission rewrites the archive to append its
5	// revision, and the stored alert processing records used to be decoded
6	// into structs on the way: a saved "version":null came back as an object
7	// full of zero values, an incomplete declaration as zero-filled
8	// parameters, and a repeated field collapsed to whichever value won. A
9	// processing record's saved detection-version declaration is the evidence
10	// of its generation time — an unrelated review must never repair,
11	// complete, replace, drop or merge it, and must never borrow parameters
12	// from the block's report, the currently enabled version or a same-id
13	// registered version. The declarations themselves stay legal JSON values;
14	// the submit only has to leave them exactly as stored.
15	
16	import (
17		"bytes"
18		"encoding/json"
19		"errors"
20		"os"
21		"path/filepath"
22		"reflect"
23		"strings"
24		"testing"
25	)
26	
27	// alertRecordsRaw returns every stored alert processing record as its raw
28	// stored document, whitespace-normalized so a rewrite that only re-indents
29	// the archive still compares equal while key order, duplicate fields and
30	// explicit nulls are preserved exactly.
31	func alertRecordsRaw(t *testing.T, dir string) []string {
32		t.Helper()
33		var doc struct {
34			Alerts []json.RawMessage `json:"alerts"`
35		}
36		if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
37			t.Fatal(err)
38		}
39		if len(doc.Alerts) == 0 {
40			t.Fatal("expected stored alert records")
41		}
42		out := make([]string, len(doc.Alerts))
43		for i, raw := range doc.Alerts {
44			var buf bytes.Buffer
45			if err := json.Indent(&buf, raw, "", "  "); err != nil {
46				t.Fatalf("stored alert record %d is not valid JSON: %v", i, err)
47			}
48			out[i] = buf.String()
49		}
50		return out
51	}
52	
53	// TestSubmitReviewPreservesAlertRecordDeclarations runs the decay matrix
54	// over the alert record's saved declaration — an explicit null, a missing
55	// key, an empty or incomplete object, a wrong-typed parameter — plus a
56	// complete declaration the registry never carried. A successful review
57	// submission must leave every one byte for byte in content: nothing is
58	// completed, zero-filled, replaced, dropped or borrowed from the report,
59	// the enabled version or the registry.
60	func TestSubmitReviewPreservesAlertRecordDeclarations(t *testing.T) {
61		cases := []struct {
62			name  string
63			value any  // nil means an explicit JSON null
64			drop  bool // remove the version key entirely
65		}{
66			{"null", nil, false},
67			{"missing key", nil, true},
68			{"empty object", map[string]any{}, false},
69			{"incomplete object", map[string]any{"id": "candC"}, false},
70			{"wrong-typed parameter", map[string]any{
71				"id": "candC",
72				"rules": map[string]any{
73					"sandwich":     map[string]any{"enabled": false, "severity": 3},
74					"displacement": map[string]any{"enabled": true, "severity": 4, "multiplier": "2"},
75				},
76			}, false},
77			{"complete but never registered", map[string]any{
78				"id": "never-registered",
79				"rules": map[string]any{
80					"sandwich":     map[string]any{"enabled": true, "severity": 5},
81					"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 9},
82				},
83			}, false},
84		}
85		for _, tc := range cases {
86			t.Run(tc.name, func(t *testing.T) {
87				dir := setupAlertHistoryCorruptArchive(t)
88				if tc.drop {
89					dropStoredAlertVersionKey(t, dir, alertHistoryChain, alertHistoryBlock,
90						alertHistoryTx, alertHistoryKind, alertHistoryChannel)
91				} else {
92					replaceStoredAlertVersion(t, dir, alertHistoryChain, alertHistoryBlock,
93						alertHistoryTx, alertHistoryKind, alertHistoryChannel, tc.value)
94				}
95				before := alertRecordsRaw(t, dir)
96	
97				res, err := SubmitReview(dir, submitTarget("s-1", 0))
98				if err != nil || !res.Created || res.Version != 1 {
99					t.Fatalf("submission against the intact report = %+v %v", res, err)
100				}
101				if after := alertRecordsRaw(t, dir); !reflect.DeepEqual(before, after) {
102					t.Fatalf("submission rewrote the alert record:\nbefore %s\nafter  %s",
103						strings.Join(before, "\n"), strings.Join(after, "\n"))
104				}
105	
106				// The new revision is visible through the history query.
107				hist, err := ReviewHistoryQuery(dir, "1", "0xblk", historyTargetTx, historyTargetKind)
108				if err != nil || hist.Version != 1 || hist.Status != ReviewStatusReal ||
109					len(hist.Revisions) != 1 {
110					t.Fatalf("review history = %+v %v", hist, err)
111				}
112	
113				// The alert history query still judges the record by its own
114				// saved declaration: damage the submit preserved is neither
115				// repaired into a success nor explained as the built-in rules,
116				// and a self-contained declaration is used exactly as saved.
117				got, herr := AlertHistory(dir, alertHistoryChain, alertHistoryChannel, 0, 100)
118				if tc.name == "complete but never registered" {
